// Builds both emails from the website form submission.
// All user input is HTML-escaped before it goes into the email body.
const b = $input.first().json.body || {};

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const clean = (v, max) => String(v ?? '').trim().slice(0, max);

const name = clean(b.name, 200);
const email = clean(b.email, 254);
const phone = clean(b.phone, 50);
const message = clean(b.message, 2000);
const page = clean(b.page, 500);
const source = clean(b.source, 50);
const sourceLabel = {
  'home-quick-contact': 'Homepage - Quick Contact',
  'contact-page': 'Contact page - Send Us Your Query',
}[source] || source || 'Website';

let when = b.submitted_at || new Date().toISOString();
try {
  when = new Date(when).toLocaleString('en-US', { timeZone: 'America/Phoenix', dateStyle: 'medium', timeStyle: 'short' }) + ' (Arizona)';
} catch (e) {}

const row = (label, value) => value
  ? `<tr><td style="padding:8px 12px;color:#55646C;font-weight:600;vertical-align:top;white-space:nowrap">${label}</td><td style="padding:8px 12px;color:#2D3A42">${value}</td></tr>`
  : '';

const wrap = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;background:#F5F6F8;padding:24px">
<div style="max-width:600px;margin:0 auto;background:#ffffff;border-radius:8px;overflow:hidden">
<div style="background:#003A3A;padding:18px 24px;color:#ffffff;font-size:18px;font-weight:bold"><span style="color:#FFB400">IRA</span> IDEAS LLC</div>
<div style="padding:24px;color:#2D3A42;font-size:15px;line-height:1.6">${inner}</div>
</div></div>`;

const adminHtml = wrap(`
<h2 style="margin:0 0 12px;font-size:20px;color:#003A3A">New website enquiry</h2>
<table style="border-collapse:collapse;width:100%;font-size:15px">
${row('Name', esc(name))}
${row('Email', `<a href="mailto:${esc(email)}">${esc(email)}</a>`)}
${row('Phone', esc(phone))}
${row('Form', esc(sourceLabel))}
${row('Page', esc(page))}
${row('Received', esc(when))}
${row('Country', esc(b.ip_country))}
</table>
<h3 style="margin:20px 0 8px;font-size:16px;color:#003A3A">Message</h3>
<div style="white-space:pre-wrap;background:#F5F6F8;border-left:4px solid #FFB400;padding:12px 16px">${esc(message)}</div>
<p style="margin-top:20px;font-size:13px;color:#7A7A7A">Reply to this email to answer ${esc(name || email)} directly.</p>`);

const firstName = name.split(/\s+/)[0];
const clientHtml = wrap(`
<p>Hi ${esc(firstName) || 'there'},</p>
<p>Thank you for contacting IRA Ideas. We've received your message and will get back to you as soon as possible, usually within one business day.</p>
<p>If your question is time-sensitive, you can book a Retirement Certainty Session with attorney Tim Berry:</p>
<p><a href="https://iraideas.com/retirement-certainty-session/" style="display:inline-block;background:#FFB400;color:#ffffff;text-decoration:none;font-weight:bold;padding:12px 22px;border-radius:4px">Book An Appointment &rarr;</a></p>
<p>Or reach us at <a href="tel:+16029001855">602-900-1855</a> or <a href="mailto:tim@iraideas.com">tim@iraideas.com</a>.</p>
<p>Best regards,<br>Tim Berry<br>IRA Ideas LLC</p>
<p style="margin-top:24px;font-size:12px;color:#7A7A7A">You're receiving this because this email address was entered on a contact form at iraideas.com. If that wasn't you, you can ignore this message.</p>`);

return [{ json: {
  name, email, phone, message, page, source, sourceLabel, when,
  adminSubject: `New website enquiry from ${name || email} (${sourceLabel})`,
  adminHtml,
  clientSubject: 'We received your message - IRA Ideas',
  clientHtml,
} }];
